var i=`0104-kibinai`;var t=`world-0104`;var o=`LT`;var a=`northern-europe`;var s=4;var r=87;var g={en:`Kibinai`,ua:`Кібінай`};var l={en:`A classic dish from Lithuania, featuring ground lamb, yellow onion, chicken egg, parsley. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Литва. Основні складники: фарш з ягнятини, жовта цибуля, куряче яйце, петрушка. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var u=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 24 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 24 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:24,i:[[`all-purpose-flour`,500,`g`],[`unsalted-butter`,175,`g`],[`water`,200,`ml`],[`table-salt`,5,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:12,i:[[`ground-lamb`,420,`g`],[`yellow-onion`,170,`g`],[`ground-black-pepper`,null,`to_taste`],[`caraway-seeds`,3,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:14,i:[]},{en:`Bake in a preheated 180°C oven for about 35 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 35 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:35,i:[[`chicken-egg`,1,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`parsley`,14,`g`]]}];var d={slug:i,id:t,country:`LT`,region:a,servings:4,minutes:87,title:g,text:l,steps:u};export{o as country,d as default,t as id,r as minutes,a as region,s as servings,i as slug,u as steps,l as text,g as title};